-- CAREEROS P6-T02: email suppression list. The CREATE TABLE and its CHECK constraints are generated by drizzle-kit; the
-- row-level security, the definer functions and the grants are written by hand, following P3-T05. Runs as the migration
-- (owner) role. Down migration: down.sql in this folder.
--> statement-breakpoint
CREATE TABLE "email_suppression" (
	"email_hash" text PRIMARY KEY,
	"reason" text NOT NULL,
	"provider_email_id" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "email_suppression_hash_check" CHECK ("email_hash" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "email_suppression_reason_check" CHECK ("reason" in ('bounce', 'complaint'))
);
--> statement-breakpoint
-- 1. email_suppression: global and platform only, like billing_provider_plan. A bounce or a complaint is about the
-- address, not an organization, so there is no organization_id and no tenant data: only sha256(lower-cased address).
-- The app role has NO privilege and NO policy on it; the two definer functions below are the only way in. The REVOKE is
-- repeated in infra/db/bootstrap-roles.sql because that script's blanket GRANT would undo it.
ALTER TABLE "email_suppression" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "email_suppression" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
DROP POLICY IF EXISTS "owner_access" ON "email_suppression";--> statement-breakpoint
CREATE POLICY "owner_access" ON "email_suppression" TO CURRENT_USER USING (true) WITH CHECK (true);--> statement-breakpoint
DO $$ BEGIN
	IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'careeros_app') THEN
		REVOKE ALL ON TABLE public.email_suppression FROM careeros_app;
	END IF;
END $$;--> statement-breakpoint
-- 2. careeros_email_is_suppressed: whether the address with this hash must not be mailed. Answers true or false, never a row.
CREATE OR REPLACE FUNCTION public.careeros_email_is_suppressed(p_hash text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
	SELECT EXISTS (SELECT 1 FROM public.email_suppression WHERE email_hash = p_hash)
$$;--> statement-breakpoint
-- 3. careeros_email_suppress: records a hard bounce or a complaint. An address that is already suppressed keeps the row it
-- has (the first reason wins), so a repeated event is a no-op. Only a well-formed hash and a known reason are accepted.
CREATE OR REPLACE FUNCTION public.careeros_email_suppress(p_hash text, p_reason text, p_provider_email_id text)
RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
BEGIN
	IF p_hash IS NULL OR p_hash !~ '^[0-9a-f]{64}$' THEN
		RAISE EXCEPTION 'careeros_email_suppress: invalid hash';
	END IF;
	IF p_reason IS NULL OR p_reason NOT IN ('bounce', 'complaint') THEN
		RAISE EXCEPTION 'careeros_email_suppress: invalid reason';
	END IF;
	IF p_provider_email_id IS NOT NULL AND p_provider_email_id !~ '^[A-Za-z0-9_.:-]{1,128}$' THEN
		RAISE EXCEPTION 'careeros_email_suppress: invalid provider email id';
	END IF;
	INSERT INTO public.email_suppression (email_hash, reason, provider_email_id)
	VALUES (p_hash, p_reason, p_provider_email_id)
	ON CONFLICT (email_hash) DO NOTHING;
END
$$;--> statement-breakpoint
COMMENT ON TABLE "email_suppression" IS 'Addresses the email provider reported as hard bounced or complained about (P6-T02). sha256 of the lower-cased address only; reached through careeros_email_is_suppressed and careeros_email_suppress.';--> statement-breakpoint
DO $$ BEGIN
	REVOKE ALL ON FUNCTION public.careeros_email_is_suppressed(text) FROM PUBLIC;
	REVOKE ALL ON FUNCTION public.careeros_email_suppress(text, text, text) FROM PUBLIC;
	IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'careeros_app') THEN
		GRANT EXECUTE ON FUNCTION public.careeros_email_is_suppressed(text) TO careeros_app;
		GRANT EXECUTE ON FUNCTION public.careeros_email_suppress(text, text, text) TO careeros_app;
	END IF;
END $$;
